package org.apache.dubbo.common.utils;

import org.junit.jupiter.api.Test;
import java.lang.reflect.Method;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.concurrent.CompletableFuture;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class ReflectUtilsTest {

    /**
     * Interface for testing generic return type resolution.
     * This scenario triggers the TypeVariable handling logic in getReturnTypes.
     * Specifically: public interface TypeClass<T> { CompletableFuture<T> getGenericFuture(); }
     */
    public interface GenericService<T> {
        CompletableFuture<T> getGenericFuture();
    }

    @Test
    public void testGetReturnTypesWithGenericTypeVariable() throws Exception {
        // Get the method that returns CompletableFuture<T> where T is a TypeVariable
        Method method = GenericService.class.getMethod("getGenericFuture");

        // Invoke the method under test.
        // Before the patch, this would throw ClassCastException because TypeVariable 
        // was not handled and cast directly to Class<?> in the else branch.
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        // Validate the result array is not null and has 2 elements
        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // The first element (returnType) should be the first bound of the TypeVariable.
        // Since T has no explicit bound, it defaults to Object.class.
        assertEquals(Object.class, returnTypes[0]);

        // The second element (genericReturnType) should be the TypeVariable instance itself.
        assertTrue(returnTypes[1] instanceof TypeVariable);
        TypeVariable<?> typeVariable = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVariable.getName());
    }
}

